 "content": "def transform(grid):
    """Extend each colored center in a 3-marked cardinal cross along its row and column.

    The 3s are the cross markers and remain visible; each center color paints its
    complete row and column, with vertical strokes taking precedence where
    different strokes intersect.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (0, 3) and any(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 3
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
            ):
                centers.append((r, c, color))
    # Paint horizontal and vertical strokes; retain all original 3 markers.
    for r, c, color in centers:
        for x in range(w):
            if grid[r][x] != 3:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if grid[y][c] != 3:
                out[y][c] = color
    return out
