    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    solid, hollow = [], []
    for r in range(h):
        for c in range(w):
            if all(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 3
                   for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                if grid[r][c] == 0:
                    hollow.append((r, c))
                elif grid[r][c] != 3:
                    solid.append((r, c, grid[r][c]))

    # Colored crosses project rays through their own adjacent 3 arm, stopping
    # at the next 3 marker. Horizontal strokes are below vertical strokes.
    for r, c, color in solid:
        for dc in (-1, 1):
            x = c + dc
            if 0 <= x < w and grid[r][x] == 3:
                x += dc
            while 0 <= x < w and grid[r][x] != 3:
                if grid[r][x] == 0:
                    out[r][x] = color
                x += dc
    for r, c, color in solid:
        for dr in (-1, 1):
            y = r + dr
            if 0 <= y < h and grid[y][c] == 3:
                y += dr
            while 0 <= y < h and grid[y][c] != 3:
                if grid[y][c] == 0:
                    out[y][c] = color
                y += dr

    # Hollow crosses create a transparent vertical stripe through their center.
    for r, c in hollow:
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = 0
    return out
